exercise.referenceSolution:
struct Device { int id; explicit Device(int x) : id(x) {} };
class Probe : public Device { public: explicit Probe(int x) : Device(x) {} };
int inspect(const Device& d) { return d.id; }
int solve(int a,int b) { Probe x{a}, y{b}; return inspect(x)+inspect(y); }
